const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + encrypted + ':' + tag;
}

function decrypt(encryptedText) {
  const parts = String(encryptedText).split(':');
  if (parts.length !== 3) {
    throw new Error('Invalid encrypted payload format');
  }
  const iv = Buffer.from(parts[0], 'hex');
  const encrypted = parts[1];
  const tag = Buffer.from(parts[2], 'hex');
  if (iv.length !== IV_LENGTH) {
    throw new Error('Invalid IV length');
  }
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

const searchIndex = new Map();

function indexDocument(id, content) {
  const encryptedContent = encrypt(content);
  searchIndex.set(id, encryptedContent);
  return { id, status: 'indexed' };
}

function searchDocuments(query) {
  const results = [];
  for (const [id, encContent] of searchIndex.entries()) {
    const content = decrypt(encContent);
    if (content.toLowerCase().includes(query.toLowerCase())) {
      results.push({ id, snippet: content.substring(0, 100) });
    }
  }
  return results;
}

function parseContentLength(headers) {
  const clHeader = headers['content-length'];
  if (clHeader === undefined) return 0;
  return parseInt(clHeader, 10);
}

function parseTransferEncoding(headers) {
  const te = headers['transfer-encoding'];
  if (!te) return null;
  return te.trim().toLowerCase();
}

function handleRequest(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const path = url.pathname;

  let body = '';
  const contentLength = parseContentLength(req.headers);
  const transferEncoding = parseTransferEncoding(req.headers);

  // Per RFC 7230 Section 3.3.3: If Transfer-Encoding is present,
  // Content-Length MUST be ignored. Reject ambiguous requests.
  if (transferEncoding && req.headers['content-length']) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Ambiguous body framing rejected' }));
    return;
  }

  const useChunked = transferEncoding === 'chunked';

  if (useChunked) {
    req.on('data', (chunk) => {
      body += chunk.toString();
    });
  } else {
    let received = 0;
    req.on('data', (chunk) => {
      const str = chunk.toString();
      if (received + str.length <= contentLength) {
        body += str;
        received += str.length;
      } else {
        body += str.substring(0, contentLength - received);
        received = contentLength;
      }
    });
  }

  req.on('end', () => {
    try {
      if (path === '/index' && req.method === 'POST') {
        const data = JSON.parse(body);
        if (!data.id || !data.content) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing id or content' }));
          return;
        }
        const result = indexDocument(data.id, data.content);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result));
      } else if (path === '/search' && req.method === 'GET') {
        const query = url.searchParams.get('q') || '';
        const results = searchDocuments(query);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ results }));
      } else if (path === '/admin/reindex' && req.method === 'POST') {
        // Admin endpoint - requires internal network access
        const sourceIp = req.socket.remoteAddress;
        if (sourceIp === '127.0.0.1' || sourceIp === '::1') {
          searchIndex.clear();
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ status: 'index cleared' }));
        } else {
          res.writeHead(403, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Forbidden' }));
        }
      } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Not found' }));
      }
    } catch (e) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal error' }));
    }
  });
}

const server = http.createServer(handleRequest);
server.listen(3000, () => console.log('Search indexing service on port 3000'));

module.exports = { server, indexDocument, searchDocuments };
